verify:
def skill():
    tbl = {1.0: Rational('0.3413'), 1.5: Rational('0.4332'), 2.0: Rational('0.4772'), 2.5: Rational('0.4938')}
    return 1000*(tbl[1.5] + tbl[2.5])

def standard():
    tbl = {1.0: Rational('0.3413'), 1.5: Rational('0.4332'), 2.0: Rational('0.4772'), 2.5: Rational('0.4938')}
    from sympy import erf
    phi = lambda z: exp(-z**2 / 2) / sqrt(2*pi)
    t = Symbol('t', positive=True)
    H = lambda tt: integrate(phi(Symbol('u')), (Symbol('u'), tt - 2, tt + 2))
    # 실제 정규분포로 t 후보에서 단조 감소를 수치 확인
    Phi = lambda z: (1 + erf(z / sqrt(2))) / 2
    ts = [Rational(1, 2) + Rational(i, 4) for i in range(0, 12)]
    vals = [float(Phi(x + 2) - Phi(x - 2)) for x in ts]
    assert all(vals[i] > vals[i + 1] for i in range(len(vals) - 1))
    # t=1/2 → [-3/2, 5/2] : 표의 값으로
    return 1000*(tbl[1.5] + tbl[2.5])

def unique():
    return [standard()]
